//! The corpus: every fixture must survive CSV → AST → CSV **byte for byte**.
//!
//! The fixtures under `tests/fixtures/` are generated by Python's own `csv`
//! module - `tests/test_csv_crosslib.py` at the repository root
//! re-generates them and compares them byte for byte with the committed
//! files, so the bytes this test measures are bytes two independent
//! implementations agree on rather than bytes this crate wrote for itself.
//!
//! The dialect of each fixture is read out of the fixture: the extension
//! names the delimiter and the bytes name the record separator. The
//! committed files are therefore the only source of truth here, and a
//! fixture that stops being one of the two tables below fails the test
//! rather than quietly going unchecked.
//!
//! Two fixtures are refusals rather than round trips, and the point of them
//! is that the engine says so instead of repairing the file.
//!
//! One caveat about this file, stated here because it is the kind of thing a
//! reader assumes and should not: the dialect of each fixture is read out of
//! the fixture itself, so a fixture whose bytes were quietly normalised would
//! still be read as the dialect it now holds, and this file would pass about
//! the wrong bytes. What catches that is not this file but
//! `tests/test_csv_crosslib.py`, which regenerates every fixture with Python's
//! own `csv` module and compares it byte for byte with the committed file - a
//! normalised CRLF fixture stops matching and the comparison fails. The Rust
//! side reads the same committed bytes, so the two implementations are
//! measured on one input rather than on two that merely look alike.

use std::fs;
use std::path::{Path, PathBuf};

use pyrs_csv::{
    CsvOptions, Delimiter, LineTerminator, from_csv_with_options, to_csv_text_with_options,
};

/// The fixtures that must survive the round trip unchanged.
const FIXTURES: &[&str] = &[
    "basic.csv",
    "bom.csv",
    "crlf.csv",
    "doubled_quotes.csv",
    "empty_cells.csv",
    "embedded_newline.csv",
    "leading_zeros.csv",
    "non_ascii.csv",
    "quoted_separator.csv",
    "tabbed.tsv",
    "types.csv",
];

/// The fixtures the reader must refuse, and the code it must refuse them with.
const REFUSED: &[(&str, &str)] = &[
    ("duplicate_header.csv", "E-CSV-003"),
    ("ragged_row.csv", "E-CSV-002"),
];

/// Where the corpus lives.
fn fixtures_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
}

/// The bytes of a fixture.
fn read(name: &str) -> Vec<u8> {
    let path = fixtures_dir().join(name);
    fs::read(&path).unwrap_or_else(|error| panic!("{}: {error}", path.display()))
}

/// The dialect a fixture is written in, read out of the fixture itself.
fn options_for(name: &str, text: &str) -> CsvOptions {
    CsvOptions {
        delimiter: if name.ends_with(".tsv") {
            Delimiter::Tab
        } else {
            Delimiter::Comma
        },
        // A fixture that holds a CRLF is a CRLF fixture; the embedded-newline
        // fixture holds a bare LF inside a quoted field and is not one.
        line_terminator: if text.contains("\r\n") {
            LineTerminator::CrLf
        } else {
            LineTerminator::Lf
        },
        ..CsvOptions::default()
    }
}

/// The fixture's text, without a leading byte-order mark.
///
/// The mark is an encoding artifact rather than data - the engine strips it
/// on the way in, the way the docs say it does - so it is the one thing in
/// the corpus that cannot travel back out. The fixture behind a mark is
/// therefore compared without it, and the rest of the file must be exact.
fn body_without_bom(bytes: &[u8]) -> &[u8] {
    const BOM: &[u8] = &[0xef, 0xbb, 0xbf];
    bytes.strip_prefix(BOM).unwrap_or(bytes)
}

#[test]
fn every_fixture_survives_the_round_trip_byte_for_byte() {
    for name in FIXTURES {
        let bytes = read(name);
        let body = body_without_bom(&bytes);
        let text = String::from_utf8(body.to_vec()).expect("a fixture is UTF-8");
        let options = options_for(name, &text);

        let node = from_csv_with_options(&text, &options)
            .unwrap_or_else(|error| panic!("{name} does not parse: {error}"));
        let written = to_csv_text_with_options(&node, &options)
            .unwrap_or_else(|error| panic!("{name} does not write back: {error}"));

        assert_eq!(
            written.as_bytes(),
            body,
            "{name} did not survive CSV -> AST -> CSV byte for byte"
        );
    }
}

#[test]
fn the_corpus_holds_no_fixture_the_test_does_not_know() {
    let mut found: Vec<String> = fs::read_dir(fixtures_dir())
        .expect("the corpus directory is readable")
        .filter_map(|entry| entry.ok())
        .filter(|entry| entry.path().is_file())
        .map(|entry| entry.file_name().to_string_lossy().into_owned())
        .collect();
    found.sort();

    let mut known: Vec<String> = FIXTURES
        .iter()
        .map(|name| (*name).to_string())
        .chain(REFUSED.iter().map(|(name, _)| (*name).to_string()))
        .collect();
    known.sort();

    assert_eq!(
        found, known,
        "the corpus directory and the test's two tables disagree"
    );
}

/// The byte-for-byte promise covers the corpus, not every possible CSV cell.
///
/// A quoted cell that the core schema types is written back unquoted: `"true"`
/// resolves to a boolean and comes back as `true`. That is the inference
/// decision the design locks — quoting is RFC 4180 syntax, not a type
/// assertion — so it is not a round-trip bug. It is stated as a test because
/// the corpus has no such fixture, and a reader of `every_fixture_survives...`
/// should not infer that the promise is wider than the corpus it measures.
///
/// Callers who need every cell to stay a string pass `infer: false` (or
/// `--no-infer` in the CLI); with inference off, the spelling survives.
#[test]
fn a_quoted_typed_cell_is_re_inferred_and_loses_its_quotes() {
    let options = CsvOptions::default();
    let typed = "flag,note\n\"true\",\"007\"\n";
    let node = from_csv_with_options(typed, &options).expect("the typed fixture parses");
    let written = to_csv_text_with_options(&node, &options).expect("the typed fixture writes back");
    assert_eq!(
        written, "flag,note\ntrue,007\n",
        "the inferred spelling is written bare"
    );

    let options = CsvOptions {
        infer_types: false,
        ..CsvOptions::default()
    };
    let node = from_csv_with_options(typed, &options).expect("the string fixture parses");
    let written =
        to_csv_text_with_options(&node, &options).expect("the string fixture writes back");
    assert_eq!(written, typed, "with inference off the spelling survives");
}

#[test]
fn a_cell_reading_007_comes_back_as_007() {
    // The claim the whole engine rests on: the spelling travels, the type is
    // resolved at read time. A cell reading `007` resolves to the integer 7
    // and is still written back as `007`.
    let bytes = read("leading_zeros.csv");
    let text = String::from_utf8(bytes).expect("a fixture is UTF-8");
    let node = from_csv_with_options(&text, &CsvOptions::default()).expect("the fixture parses");
    let written =
        to_csv_text_with_options(&node, &CsvOptions::default()).expect("the fixture writes back");

    assert!(
        written.contains("007,"),
        "the leading zero was lost: {written:?}"
    );
    assert!(
        !written.contains("\n7,"),
        "the cell was re-serialized as a number: {written:?}"
    );
}

#[test]
fn a_ragged_row_is_refused_rather_than_repaired() {
    let bytes = read("ragged_row.csv");
    let text = String::from_utf8(bytes).expect("a fixture is UTF-8");
    let error = from_csv_with_options(&text, &CsvOptions::default())
        .expect_err("a row with too few cells is refused");
    assert_eq!(error.code(), "E-CSV-002");
    // The refusal names the line, so a caller can find the row in the file.
    assert!(error.to_string().contains('2'), "{error}");
}

#[test]
fn a_duplicate_column_is_refused_rather_than_repaired() {
    let bytes = read("duplicate_header.csv");
    let text = String::from_utf8(bytes).expect("a fixture is UTF-8");
    let error = from_csv_with_options(&text, &CsvOptions::default())
        .expect_err("a header that names a column twice is refused");
    assert_eq!(error.code(), "E-CSV-003");
    assert!(error.to_string().contains('a'), "{error}");
}
